import React, { useState, useEffect } from 'react';
import { checkServerStatus } from '../services/api';

const ServerStatus = () => {
  const [status, setStatus] = useState('checking');
  const [error, setError] = useState(null);
  const [details, setDetails] = useState(null);

  useEffect(() => {
    const checkStatus = async () => {
      try {
        const response = await checkServerStatus();
        setStatus('online');
        setDetails(response);
        setError(null);
      } catch (err) {
        setStatus('offline');
        setError(err.message);
        setDetails(null);
      }
    };

    checkStatus();
  }, []);

  return (
    <div className="p-4 bg-white rounded-lg shadow">
      <h2 className="text-lg font-semibold text-brown mb-4">Server Status</h2>

      <div className="space-y-4">
        <div className="flex items-center">
          <span className="text-sm font-medium text-brown">Status:</span>
          <span className={`ml-2 px-2 py-1 text-xs font-semibold rounded-full ${
            status === 'online' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
          }`}>
            {status === 'online' ? 'Online' : 'Offline'}
          </span>
        </div>

        {error && (
          <div className="p-3 bg-red-50 border border-red-200 rounded-md">
            <p className="text-sm text-red-600">{error}</p>
          </div>
        )}

        {details && (
          <div className="p-3 bg-green-50 border border-green-200 rounded-md">
            <pre className="text-sm text-green-800 overflow-auto">
              {JSON.stringify(details, null, 2)}
            </pre>
          </div>
        )}
      </div>
    </div>
  );
};

export default ServerStatus;
